    "path": "desktop/package.json",
    "lang": "json",
    "content": "{\n  \"name\": \"xultra-desktop\",\n  \"version\": \"1.0.2\",\n  \"description\": \"Application de bureau XULTRA — enveloppe native pour xultra.space\",\n  \"main\": \"src/main.js\",\n  \"private\": true,\n  \"author\": {\n    \"name\": \"XULTRA\",\n    \"email\": \"contact@xultra.space\"\n  },\n  \"homepage\": \"https://xultra.space\",\n  \"license\": \"UNLICENSED\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/Baki345/ressources.xultra.space.git\"\n  },\n  \"scripts\": {\n    \"start\": \"electron .\",\n    \"dist:win\": \"electron-builder --win\",\n    \"dist:mac\": \"electron-builder --mac\",\n    \"dist:linux\": \"electron-builder --linux\",\n    \"dist\": \"electron-builder -mwl\",\n    \"dist:vpn\": \"electron-builder --config electron-builder-vpn.json -mwl\"\n  },\n  \"devDependencies\": {\n    \"electron\": \"^32.0.0\",\n    \"electron-builder\": \"^25.0.0\"\n  },\n  \"build\": {\n    \"appId\": \"space.xultra.desktop\",\n    \"productName\": \"XULTRA\",\n    \"directories\": {\n      \"output\": \"dist\",\n      \"buildResources\": \"build\"\n    },\n    \"files\": [\n      \"src/**/*\",\n      \"build/icon.png\",\n      \"build/tray.png\",\n      \"build/tray@16.png\",\n      \"build/badges/**/*\"\n    ],\n    \"mac\": {\n      \"icon\": \"build/icon.png\",\n      \"category\": \"public.app-category.social-networking\",\n      \"target\": [\n        \"dmg\",\n        \"zip\"\n      ]\n    },\n    \"win\": {\n      \"icon\": \"build/icon.png\",\n      \"target\": [\n        \"nsis\",\n        \"portable\"\n      ]\n    },\n    \"linux\": {\n      \"icon\": \"build/icon.png\",\n      \"category\": \"Network;Chat;\",\n      \"target\": [\n        \"AppImage\",\n        \"deb\"\n      ],\n      \"maintainer\": \"contact@xultra.space\"\n    },\n    \"nsis\": {\n      \"oneClick\": false,\n      \"allowToChangeInstallationDirectory\": true,\n      \"createDesktopShortcut\": true,\n      \"createStartMenuShortcut\": true\n    },\n    \"extraResources\": [\n      {\n        \"from\": \"resources/wireguard-go/${platform}-${arch}\",\n        \"to\": \"wireguard-go\",\n        \"filter\": [\n          \"**/*\"\n        ]\n      },\n      {\n        \"from\": \"resources/wstunnel/${platform}-${arch}\",\n        \"to\": \"wstunnel\",\n        \"filter\": [\n          \"**/*\"\n        ]\n      }\n    ]\n  },\n  \"dependencies\": {\n    \"@vscode/sudo-prompt\": \"^9.3.2\"\n  }\n}\n",
