  const grantedByLabel=meta.planAssignedBy==='hunter_tier5'?'👑 Palier Bug Hunter ultime — Légende du Bug (50 bugs résolus)':meta.planAssignedBy==='stripe_purchase'?'💳 Achat par carte':meta.planAssignedBy==='coins_purchase'?'🪙 Achat avec des IXin Coins':meta.planAssignedBy==='elite_badge'?'💎 Badge ÉLITE IXin':(meta.planAssignedBy||'');
