/* ===== Appels vocaux (WebRTC) ===== */
function wireCallDiagnostics(pc){
  /* Le signaling (offre/réponse via Appwrite) peut parfaitement réussir alors
     que la connexion ICE réelle échoue derrière (relais TURN gratuit
     surchargé, NAT symétrique...) : dans ce cas l'appel a l'air "connecté"
     côté UI mais aucun son/vidéo ne circule, des deux côtés à la fois. Ces
     logs permettent de faire la différence la prochaine fois plutôt que de
     deviner : si iceConnectionState reste sur "checking" ou passe à "failed"
     malgré tout, c'est le relais TURN qui est en cause, pas l'app. */
  pc.oniceconnectionstatechange=function(){xlog('call_ice_state',{state:pc.iceConnectionState});};
  // Affiche l'état de connexion en direct sous le minuteur (idée demandée
  // explicitement, façon Discord : "Connexion RTC en cours…") — seulement
  // une fois l'appel décroché des deux côtés (callLive) : avant ça,
  // "Sonne…"/"En attente…" restent plus parlants qu'un état ICE brut, et le
  // remplacer prématurément donnerait l'impression fausse que l'autre a déjà
  // répondu.
  pc.onconnectionstatechange=function(){
    xlog('call_conn_state',{state:pc.connectionState});
    if(callPc!==pc||!callLive)return;
    if(pc.connectionState==='connecting'){clearCallDisconnectWatch();setCallStatusLabel('Connexion RTC en cours…');}
    else if(pc.connectionState==='connected'){clearCallDisconnectWatch();setCallStatusLabel('En appel…');}
    else if(pc.connectionState==='disconnected'){
      setCallStatusLabel('Reconnexion…');
      // Un navigateur reste parfois bloqué sur "disconnected" indéfiniment
      // sans jamais atteindre "failed" (crash de l'autre côté, coupure
      // réseau dure...) — sans ce filet, activeCallDoc restait peuplé pour
      // toujours et bloquait silencieusement tout appel entrant/sortant
      // futur (voir subscribeIncomingCalls) : un vrai "appel fantôme" signalé
      // par l'utilisateur. On laisse une chance de reconnexion spontanée
      // (comportement WebRTC normal en cas de blip réseau bref) avant de
      // considérer que c'est fini.
      if(!callDisconnectTimeoutId)callDisconnectTimeoutId=setTimeout(function(){
        callDisconnectTimeoutId=null;
        if(callPc===pc&&callLive&&pc.connectionState!=='connected'){
          setCallStatusLabel('Connexion perdue');handleLocalConnectionLost();
        }
      },8000);
    }
    else if(pc.connectionState==='failed'){clearCallDisconnectWatch();setCallStatusLabel('Connexion perdue');handleLocalConnectionLost();}
  };
  pc.onicegatheringstatechange=function(){xlog('call_ice_gathering',{state:pc.iceGatheringState});};
}
const FALLBACK_ICE_SERVERS={iceServers:[
  {urls:'stun:stun.l.google.com:19302'},
  {urls:'stun:stun1.l.google.com:19302'},
  {urls:'stun:openrelay.metered.ca:80'},
  {urls:'turn:openrelay.metered.ca:80',username:'openrelayproject',credential:'openrelayproject'},
  {urls:'turn:openrelay.metered.ca:443',username:'openrelayproject',credential:'openrelayproject'},
  {urls:'turn:openrelay.metered.ca:443?transport=tcp',username:'openrelayproject',credential:'openrelayproject'}
]};
let cachedIceServers=null,cachedIceServersExp=0;
async function getIceServers(){
  const now=Date.now();
  if(cachedIceServers&&now<cachedIceServersExp)return cachedIceServers;
  try{
    const res=await authGet('/api/call/turn-credentials');
    cachedIceServers={iceServers:res.iceServers};
    cachedIceServersExp=now+1000*60*60*4;
    return cachedIceServers;
  }catch(e){
    xlog('turn_credentials_fail',{msg:(e&&e.message)||String(e)});
    return FALLBACK_ICE_SERVERS;
  }
}
